adcs_mat3_t c_ct;
double det_val;
double frob_err;
size_t i, j;

/* 1. Null pointer checks */
if ((dcm == NULL) || (valid == NULL) || (determinant == NULL) || (orthogonality_error == NULL)) {
    return ADCS_E_NULL;
}

/* 2. Validate tolerance */
if ((!isfinite(tolerance)) || (tolerance < 0.0)) {
    return ADCS_E_RANGE;
}

/* 3. Check matrix finiteness */
for (i = 0; i < 3; i++) {
    for (j = 0; j < 3; j++) {
        if (!isfinite(dcm->m[i][j])) {
            return ADCS_E_RANGE;
        }
    }
}

/* 4. Calculate determinant */
det_val = adcs_mat3_det(dcm);

/* 5. Check positive determinant */
if (det_val <= 0.0) {
    return ADCS_E_RANGE;
}

/* 6. Compute C * C^T */
adcs_mat3_t ct = adcs_mat3_transpose(dcm);
c_ct = adcs_mat3_mul(dcm, &ct);

/* 7. Compute Frobenius error of C*C^T from Identity */
frob_err = adcs_mat3_frobenius_error_identity(&c_ct);

/* 8. Check against tolerance */
if (frob_err > tolerance) {
    return ADCS_E_RANGE;
}

/* 9. Assign output values */
*determinant = det_val;
*orthogonality_error = frob_err;
*valid = TRUE32;

return ADCS_OK;

